<?php
if (isset($_SERVER['SCRIPT_FILENAME']) && realpath($_SERVER['SCRIPT_FILENAME']) === __FILE__) { http_response_code(404); exit; }   // include-only: never executable directly
/** Control Center screens for advertising and sponsorship revenue (Phase 7F), inside the existing Advertising module. Roles: owner and sales see everything; write actions follow the CRM roles (owner-only for approvals, activation, money and package settings). Every value is escaped. */
require_once __DIR__ . '/ad_report.php';

function ad_h($s): string { return htmlspecialchars((string)$s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function ad_url(array $q = []): string { return '/admin-center.php?' . http_build_query(['m' => 'advertising'] + $q); }
function ad_money(int $minor, string $cur): string { return ad_h(crm_money_format($minor, $cur)); }
function ad_messages(): array { return ['ok' => 'Saved.', 'forbidden' => 'Your role does not allow that action.', 'not_migrated' => 'The advertising migration (database/phase7f_advertising.sql) has not been applied on this server.', 'transition_invalid' => 'That status change is not allowed from the current status.', 'package_required' => 'Choose a package first.', 'campaign_not_approved' => 'The owner must approve the campaign first (disclosure label and safe landing URL) in the CRM campaign page.', 'dates_required' => 'Set the start and end dates first.',
  'price_required' => 'Record the agreed price and currency first.', 'booking_conflict' => 'Another booking already uses this inventory for these dates (capacity reached or the tool already has a placement).', 'payment_or_override_required' => 'Payment is not fully received: enter a note giving the reason the campaign may be scheduled anyway (owner decision).', 'use_activation' => 'Use the activation button (owner approval).', 'confirmation_required' => 'Tick the confirmation first.', 'disclosure_label_required' => 'The campaign needs a disclosure label (Sponsored, Advertisement or Partner content).',
  'landing_url_required' => 'The campaign needs a safe landing URL.', 'dates_invalid' => 'The dates are not valid (the end date must not be in the past).', 'tool_unknown' => 'Choose a tool from the directory.', 'tool_not_published' => 'Only a published tool can be featured.', 'tool_already_placed' => 'This tool already has an active public placement.', 'approved_for_start_date' => 'Approved: the placement will start on the start date when the daily housekeeping runs.', 'agreement_exists' => 'An agreement already exists for this booking.', 'status_not_ready' => 'Move the booking to Proposal sent first.', 'duplicate_entry' => 'This invoice or payment reference is already recorded for the contract.',
  'reference_required' => 'Enter a reference (invoice or payment number).', 'received_exceeds_invoiced' => 'Received cannot exceed invoiced.', 'no_agreement' => 'Create the agreement first.', 'contract_not_active' => 'Confirm the signed agreement first (owner).', 'booking_exists' => 'This enquiry already has a booking.', 'closed' => 'The booking is closed.', 'price_locked_by_agreement' => 'The price is fixed by the agreement; change it through a new agreement.', 'payment_link_invalid' => 'The payment link must be an https URL.']; }
function ad_msg(string $c): string { return ad_messages()[$c] ?? 'Not saved: ' . str_replace('_', ' ', $c) . '.'; }
function ad_select(string $n, string $l, array $o, string $sel = '', bool $blank = false): string { $h = '<label for="f_' . ad_h($n) . '">' . ad_h($l) . '<select id="f_' . ad_h($n) . '" name="' . ad_h($n) . '">' . ($blank ? '<option value="">—</option>' : ''); foreach ($o as $k => $v) $h .= '<option value="' . ad_h($k) . '"' . ((string)$k === $sel ? ' selected' : '') . '>' . ad_h($v) . '</option>'; return $h . '</select></label>'; }
function ad_form(string $act, array $hidden, string $inner, string $btn, string $class = 'tForm panel'): string { $o = '<form class="' . ad_h($class) . '" method="post" action="/admin-center.php?m=advertising" novalidate>' . admt_csrf() . '<input type="hidden" name="act" value="' . ad_h($act) . '">'; foreach ($hidden as $k => $v) $o .= '<input type="hidden" name="' . ad_h($k) . '" value="' . ad_h($v) . '">'; return $o . $inner . '<button class="admBtn" type="submit">' . ad_h($btn) . '</button></form>'; }
function ad_table(string $cap, array $head, array $rows, string $empty = 'Nothing recorded yet.'): string {
  if (!$rows) return '<p class="small">' . ad_h($empty) . '</p>'; $o = '<div class="scroll" role="region" tabindex="0" aria-label="' . ad_h($cap) . '"><table><caption class="sr" style="position:absolute;left:-999px">' . ad_h($cap) . '</caption><thead><tr>'; foreach ($head as $h) $o .= '<th scope="col">' . ad_h($h) . '</th>'; $o .= '</tr></thead><tbody>';
  foreach ($rows as $r) { $o .= '<tr>'; foreach ($r as $i => $c) $o .= $i === 0 ? '<th scope="row">' . $c . '</th>' : '<td>' . $c . '</td>'; $o .= '</tr>'; } return $o . '</tbody></table></div>';
}
function ad_wrap(string $inner): string { return '<style>.adPage select,.adPage input[type=text],.adPage input[type=date],.adPage input[type=url]{min-height:44px;box-sizing:border-box}.adPage a:not(.admBtn){display:inline-flex;align-items:center;min-height:44px;min-width:44px}.adPage label:has(>input[type=checkbox]){display:inline-flex;align-items:center;gap:8px;min-height:44px}.adPage input[type=checkbox]{width:28px;height:28px}</style><div class="adPage">' . $inner . '</div>'; }
function ad_new_views(): array { return ['revenue' => 'Revenue dashboard', 'bookings' => 'Bookings', 'packages' => 'Packages and inventory', 'advertisers' => 'Advertisers', 'opportunities' => 'Sales opportunities']; }
function ad_state_badge(string $s): string { return '<span class="badge">' . ad_h(ad_statuses()[$s] ?? $s) . '</span>'; }
function ad_user_options(PDO $pdo): array { $o = []; foreach (crm_users_list($pdo) as $u) $o[(string)$u['id']] = (string)$u['display_name']; return $o; }
function ad_tool_options(): array { $o = ['' => '(none)']; foreach (ad_catalogue() as $id => $t) $o[(string)$id] = (string)($t['name'] ?? $id); asort($o); return $o; }

function ad_view_revenue(PDO $pdo): string {
  $d = ad_dashboard($pdo); $o = '<h2>Advertising revenue</h2><p class="small">Every figure is recorded: bookings, contracts and revenue entries. Expected (agreed, not yet received) and received money are kept apart, currencies are never combined, and "no data yet" is not the same as 0.</p>';
  if (!$d['ready']) return $o . '<div class="panel admErr"><strong>Not installed.</strong> Apply <code>database/phase7f_advertising.sql</code> on a test or staging database first (after approval). Until then nothing changes anywhere.</div>';
  $any = $d['bookings'] > 0; $none = 'No bookings recorded yet (missing data, not a confirmed zero).'; $tile = fn(string $l, ?string $v, string $n) => adm_tile($l, $v, $n);
  $cur = fn(string $k) => $d['money'] ? implode(' · ', array_map(fn($c, $m) => crm_money_format($m[$k], $c), array_keys($d['money']), array_values($d['money']))) : null;
  $t = [$tile('Active advertisers', $any ? adm_n((int)$d['advertisers']) : null, $any ? 'Companies with an active or paused campaign.' : $none), $tile('Active campaigns', $any ? adm_n((int)$d['campaigns']) : null, $any ? 'Status Active.' : $none), $tile('Available sponsorship placements', $d['available'] === null ? null : adm_n((int)$d['available']), $d['available'] === null ? 'No package is marked available with a global slot.' : 'Free slots today across available global packages (category sponsorships are per category).'),
    $tile('Pending advertising enquiries', adm_n((int)$d['enquiries']), 'CRM campaigns in Inquiry or In review without a booking in progress.'), $tile('Outstanding payments', $cur('outstanding'), $d['money'] ? 'Invoiced and not yet paid, per currency.' : 'No invoices recorded yet.'), $tile('Received advertising revenue', $cur('net_received'), $d['money'] ? 'Money actually received, less refunds, per currency.' : 'No payments recorded yet.'),
    $tile('Expected (agreed, not yet received)', $cur('agreed_open'), $d['money'] ? 'Agreed price of open bookings minus what was received. Not revenue yet.' : 'No agreed prices recorded yet.'), $tile('Upcoming renewals (45 days)', $any ? adm_n(count($d['renewals'])) : null, $any ? 'Renewal date (or end date) within 45 days.' : $none), $tile('Expiring campaigns (14 days)', $any ? adm_n(count($d['expiring'])) : null, $any ? 'Ending within 14 days.' : $none)];
  $o .= adm_tiles_html($t);
  $o .= '<h3>Money by currency</h3>' . ad_table('Money by currency', ['Currency', 'Expected (agreed, open)', 'Invoiced', 'Outstanding', 'Received', 'Refunds', 'Net received'], array_map(fn($c, $m) => [ad_h($c), ad_money($m['agreed_open'], $c), ad_money($m['invoiced'], $c), ad_money($m['outstanding'], $c), ad_money($m['received'], $c), ad_ref($m['refunds'], $c), '<strong>' . ad_money($m['net_received'], $c) . '</strong>'], array_keys($d['money']), array_values($d['money'])), 'No money recorded yet (nothing agreed, invoiced or received).');
  $grp = fn(string $title, array $g) => '<h3>' . ad_h($title) . '</h3>' . ad_table($title, ['Name', 'Currency', 'Bookings', 'Agreed', 'Net received'], (function () use ($g) { $r = []; foreach ($g as $name => $by) foreach ($by as $c => $x) $r[] = [ad_h($name), ad_h($c), (int)$x['n'], ad_money($x['agreed'], $c), ad_money($x['net'], $c)]; return $r; })(), 'No bookings with a price yet.');
  $o .= $grp('Revenue by package', $d['by_package']) . $grp('Revenue by advertiser', $d['by_advertiser']);
  $tr = []; foreach ($d['trend'] as $c => $byM) foreach ($d['months'] as $m) if (isset($byM[$m])) $tr[] = [ad_h($m), ad_h($c), ad_money($byM[$m], $c)]; $o .= '<h3>Monthly advertising revenue (received, last 12 months)</h3>' . ad_table('Monthly revenue', ['Month', 'Currency', 'Received'], $tr, 'No payments received in the last 12 months (nothing recorded).');
  $o .= '<h3>Upcoming renewals</h3>' . ad_table('Renewals', ['Advertiser', 'Package', 'Renewal / end date', 'Status'], array_map(fn($r) => ['<a href="' . ad_h(ad_url(['view' => 'booking', 'id' => $r['id']])) . '">' . ad_h($r['company']) . '</a>', ad_h($r['package'] ?: '—'), ad_h($r['due']), ad_state_badge($r['status'])], $d['renewals']), 'No renewals due in the next 45 days.');
  $o .= '<h3>Expiring campaigns</h3>' . ad_table('Expiring', ['Advertiser', 'Package', 'Ends', 'Status'], array_map(fn($r) => ['<a href="' . ad_h(ad_url(['view' => 'booking', 'id' => $r['id']])) . '">' . ad_h($r['company']) . '</a>', ad_h($r['package'] ?: '—'), ad_h($r['end_date']), ad_state_badge($r['status'])], $d['expiring']), 'No campaign ends in the next 14 days.');
  return $o . '<h3>Bookings by status</h3>' . ad_table('By status', ['Status', 'Bookings'], array_map(fn($k, $n) => [ad_h(ad_statuses()[$k]), (int)$n], array_keys($d['by_status']), array_values($d['by_status'])));
}
function ad_ref(int $m, string $c): string { return ad_money($m, $c); }

function ad_booking_fields(PDO $pdo, array $b = []): string {
  $v = fn($k, $d = '') => (string)($b[$k] ?? $d); $pk = ['' => '(choose)']; foreach (ad_packages($pdo) as $p) $pk[(string)$p['id']] = $p['name'];
  return ad_select('package_id', 'Package', $pk, $v('package_id')) . ad_select('tool_slug', 'AI tool (for tool packages)', ad_tool_options(), $v('tool_slug')) . admt_field('category', 'Category (for category sponsorship)', $v('category'), []) . '<div class="row2">' . admt_field('agreed_price', 'Agreed price', ($b['agreed_price_minor'] ?? null) === null ? '' : ad_minor((int)$b['agreed_price_minor']), []) . ad_select('currency', 'Currency', array_combine(crm_currencies(), crm_currencies()), $v('currency', 'USD'), true) . '</div>'
    . ad_select('billing', 'Billing', ad_billings(), $v('billing', 'one_off')) . '<div class="row2">' . admt_field('start_date', 'Start (YYYY-MM-DD)', $v('start_date'), []) . admt_field('end_date', 'End (YYYY-MM-DD)', $v('end_date'), []) . '</div>' . admt_field('renewal_date', 'Renewal date (YYYY-MM-DD)', $v('renewal_date'), []) . admt_field('payment_link', 'Payment link (optional, https; you create it yourself)', $v('payment_link'), [], 'url')
    . ad_select('account_manager', 'Account manager', ad_user_options($pdo), $v('account_manager'), true) . admt_area('requirements', 'Campaign requirements', $v('requirements'), []) . admt_area('notes', 'Internal notes (never shown publicly)', $v('notes'), []);
}
function ad_view_bookings(PDO $pdo, array $get, array $user): string {
  $o = '<h2>Bookings</h2><p class="small">A booking turns a CRM advertising enquiry (campaign) into a package, dates, price and payment trail. Nothing is published or sent from here without the owner\'s approval.</p>'; if (!ad_ready($pdo)) return $o . '<div class="panel admErr">Needs the advertising migration.</div>'; $st = (string)($get['status'] ?? '');
  $o .= '<form method="get" action="/admin-center.php" class="tForm"><input type="hidden" name="m" value="advertising"><input type="hidden" name="view" value="bookings">' . ad_select('status', 'Status', ad_statuses(), $st, true) . '<button class="admBtn" type="submit">Filter</button> <a class="admLink" href="' . ad_h(ad_url(['export' => 'campaigns'])) . '">Export CSV</a></form>';
  $o .= ad_table('Bookings', ['#', 'Advertiser', 'Package', 'Placement', 'Dates', 'Status', 'Price', 'Payment'], array_map(function ($b) use ($pdo) { $p = ad_payment_summary($pdo, $b); return ['<a href="' . ad_h(ad_url(['view' => 'booking', 'id' => $b['id']])) . '">#' . (int)$b['id'] . '</a>', ad_h($b['company_name']), ad_h($b['package_name'] ?: '—'), ad_h($b['tool_slug'] ?: ($b['category'] ?: '—')), ad_h(($b['start_date'] ?: '—') . ' to ' . ($b['end_date'] ?: '—')), ad_state_badge($b['status']), $b['agreed_price_minor'] === null ? '—' : ad_money((int)$b['agreed_price_minor'], (string)$b['currency']), ad_h(ad_payment_state_label($p['state']))]; }, ad_bookings_list($pdo, ['status' => $st])), 'No bookings yet.');
  if (!crm_can($user['role'] ?? null, 'write')) return $o;
  $ens = $pdo->query("SELECT g.id, g.title, c.id cid, c.name company, g.status FROM crm_campaigns g JOIN crm_companies c ON c.id = g.company_id LEFT JOIN ad_booking b ON b.campaign_id = g.id WHERE b.id IS NULL AND g.is_synthetic = 0 AND g.status NOT IN ('rejected','cancelled') ORDER BY g.id DESC LIMIT 30")->fetchAll(PDO::FETCH_ASSOC);
  $o .= '<h3>Advertising enquiries without a booking</h3>' . ad_table('Enquiries', ['Enquiry', 'Company', 'CRM status', ''], array_map(fn($e) => [ad_h($e['title']), ad_h($e['company']), ad_h(crm_campaign_statuses()[$e['status']] ?? $e['status']), ad_form('ad_booking_adopt', ['campaign_id' => $e['id'], 'company_id' => $e['cid']], '', 'Create booking', 'tInline')], $ens), 'Every enquiry already has a booking.');
  $co = []; foreach ($pdo->query('SELECT id, name FROM crm_companies WHERE is_synthetic = 0 ORDER BY name LIMIT 500')->fetchAll(PDO::FETCH_ASSOC) as $c) $co[(string)$c['id']] = $c['name'];
  return $o . '<h3>New booking for a CRM company</h3>' . ad_form('ad_booking_create', [], ad_select('company_id', 'Company (existing CRM record)', $co, '', true) . ad_booking_fields($pdo), 'Create booking');
}
function ad_view_booking(PDO $pdo, int $id, array $user): string {
  $b = ad_booking_get($pdo, $id); if (!$b) return '<h2>Booking not found</h2><p><a href="' . ad_h(ad_url(['view' => 'bookings'])) . '">Back to bookings</a></p>'; $p = ad_payment_summary($pdo, $b); $m = ad_campaign_metrics($pdo, $b); $own = crm_can($user['role'] ?? null, 'approve'); $w = crm_can($user['role'] ?? null, 'write'); $rev = crm_can($user['role'] ?? null, 'revenue'); $n = fn($v) => $v === null ? 'Unavailable' : number_format((int)$v);
  $o = '<h2>Booking #' . (int)$b['id'] . ' ' . ad_state_badge($b['status']) . '</h2><div class="panel"><dl class="small"><dt>Advertiser</dt><dd>' . crm_link('company', (int)$b['company_id'], (string)$b['company_name']) . ' · ' . ad_h($b['company_website'] ?: '—') . '</dd><dt>CRM campaign</dt><dd>' . crm_link('campaign', (int)$b['campaign_id'], '#' . (int)$b['campaign_id']) . ' (' . ad_h(crm_campaign_statuses()[$b['campaign_status']] ?? $b['campaign_status']) . '; the owner approves content there: disclosure label ' . ad_h($b['disclosure_label'] ?: 'not set') . ', landing URL ' . ad_h($b['landing_url'] ?: 'not set') . ')</dd><dt>Package</dt><dd>' . ad_h($b['package_name'] ?: '—') . '</dd><dt>Placement</dt><dd>' . ad_h($b['tool_slug'] ?: ($b['category'] ?: '—')) . ($b['public_slot'] && $b['public_slot'] !== 'none' ? ' · public slot ' . ad_h($b['public_slot']) . ' (always labelled Sponsored)' : ' · no public slot for this package') . '</dd><dt>Dates / renewal</dt><dd>' . ad_h(($b['start_date'] ?: '—') . ' to ' . ($b['end_date'] ?: '—')) . ' · renewal ' . ad_h($b['renewal_date'] ?: '—') . '</dd><dt>Account manager</dt><dd>' . ad_h($b['manager_name'] ?: '—') . '</dd><dt>Price</dt><dd>' . ($b['agreed_price_minor'] === null ? '—' : ad_money((int)$b['agreed_price_minor'], (string)$b['currency']) . ' · ' . ad_h(ad_billings()[$b['billing']] ?? $b['billing'])) . '</dd>' . ($b['payment_link'] ? '<dt>Payment link</dt><dd><a href="' . ad_h($b['payment_link']) . '" rel="noopener nofollow noreferrer" target="_blank">' . ad_h($b['payment_link']) . '</a></dd>' : '') . ($b['payment_override'] ? '<dt>Scheduled before full payment</dt><dd>' . ad_h($b['payment_override']) . '</dd>' : '') . '</dl></div>';
  $o .= '<h3>Payment</h3>' . ad_table('Payment', ['Agreed', 'Invoiced', 'Received', 'Outstanding', 'Refunds', 'State'], $p['has_contract'] ? [[$p['agreed'] === null ? '—' : ad_money($p['agreed'], (string)$p['currency']), ad_money($p['invoiced'], (string)$p['currency']), ad_money($p['received'], (string)$p['currency']), ad_money($p['outstanding'], (string)$p['currency']), ad_money($p['refunds'], (string)$p['currency']), ad_h(ad_payment_state_label($p['state']))]] : [], 'No agreement yet: no money is recorded until an agreement exists.') . ($p['has_contract'] ? '<p class="small">Contract ' . crm_link('contract', (int)$b['contract_id'], '#' . (int)$b['contract_id']) . ' (' . ad_h($p['contract_status']) . '). Refunds are recorded in Finance.</p>' : '');
  $o .= '<h3>Measured performance</h3>' . ad_table('Performance', ['Measure', 'Value'], [['Campaign duration', $m['days_total'] === null ? 'Dates not set' : (int)$m['days_total'] . ' days'], ['Remaining', $m['days_remaining'] === null ? '—' : (int)$m['days_remaining'] . ' days (' . ad_h(['not_started' => 'not started', 'running' => 'running', 'ended' => 'ended', 'no_dates' => 'no dates'][$m['phase']]) . ')'], ['Outbound clicks during the campaign', $n($m['outbound'])], ['of which sponsored placement clicks', $n($m['sponsored'])], ['Tool page views', $n($m['tool_views'])], ['Impressions', 'Not measured'], ['Click-through rate', 'Not available (needs impressions)']]) . '<p class="small">Counts come from the cookie-free analytics and are a floor (visitors who block tracking or send Do-Not-Track are not counted). <a href="' . ad_h(ad_url(['view' => 'report', 'id' => $id])) . '" target="_blank" rel="noopener">Printable report</a></p>';
  $moves = array_filter(ad_statuses(), fn($k) => in_array($k, ad_transitions()[$b['status']] ?? [], true) && $k !== 'active', ARRAY_FILTER_USE_KEY); if ($w && $moves) $o .= ad_form('ad_booking_move', ['id' => $id], ad_select('to', 'Move to', $moves) . admt_field('note', 'Note (for Scheduled before full payment: the reason)', '', []), 'Change status');
  if ($own && in_array($b['status'], ['scheduled', 'paused'], true)) $o .= ad_form('ad_booking_activate', ['id' => $id], '<label><input type="checkbox" name="confirm" value="1"> I approve publishing this sponsored placement' . ($b['status'] === 'scheduled' && $b['start_date'] > ad_today() ? ' (it starts on ' . ad_h($b['start_date']) . ' when the housekeeping runs)' : ' now') . '. It is labelled Sponsored and ends on ' . ad_h($b['end_date'] ?: '—') . '.</label>', $b['status'] === 'paused' ? 'Resume' : 'Approve and activate');
  if ($rev) { if (!$b['contract_id'] && in_array($b['status'], ['proposal_sent', 'awaiting_payment', 'scheduled', 'active', 'paused'], true)) $o .= '<h3>Agreement</h3><p class="small">Creates the CRM opportunity, a one-line proposal and a DRAFT contract (not revenue) from this booking. Do it only when the advertiser has accepted.</p>' . ad_form('ad_agreement', ['id' => $id], '<label><input type="checkbox" name="confirm" value="1"> The advertiser accepted this price and these dates</label>', 'Create agreement');
    if ($b['contract_id'] && $p['contract_status'] === 'draft') $o .= ad_form('ad_agreement_confirm', ['id' => $id], '<p class="small">Confirm only if a signed agreement exists. Payments can be recorded after this.</p>', 'Confirm signed agreement');
    if ($b['contract_id'] && $p['contract_status'] === 'active') $o .= '<h3>Record an invoice or payment</h3><p class="small">Recorded in the existing contract revenue entries (so Finance counts it once). A reference is required and cannot be reused.</p>' . ad_form('ad_payment', ['id' => $id], ad_select('kind', 'Kind', ['invoiced' => 'Invoiced (outside this system)', 'received' => 'Received (money in the bank)'], 'invoiced') . admt_field('amount', 'Amount', '', []) . admt_field('date', 'Date (YYYY-MM-DD)', gmdate('Y-m-d'), []) . admt_field('reference', 'Reference (invoice or payment number)', '', []), 'Record'); }
  $h = $pdo->prepare('SELECT h.*, u.display_name FROM ad_booking_history h LEFT JOIN crm_users u ON u.id = h.changed_by WHERE h.booking_id = ? ORDER BY h.id DESC'); $h->execute([$id]); $o .= '<h3>Status history</h3>' . ad_table('History', ['When', 'From', 'To', 'Note', 'By'], array_map(fn($x) => [ad_h($x['changed_at']), ad_h(ad_statuses()[$x['from_status']] ?? '—'), ad_h(ad_statuses()[$x['to_status']] ?? $x['to_status']), ad_h($x['note'] ?: '—'), ad_h($x['display_name'] ?: 'system')], $h->fetchAll(PDO::FETCH_ASSOC)));
  if ($w && !in_array($b['status'], ['completed', 'cancelled', 'expired'], true)) $o .= '<h3>Edit the booking</h3>' . ad_form('ad_booking_update', ['id' => $id], ad_booking_fields($pdo, $b), 'Save booking'); return $o;
}
function ad_view_packages(PDO $pdo, array $user): string {
  $o = '<h2>Packages and inventory</h2><div class="panel" role="note"><strong>Proposed, not published.</strong> The packages below are configurable proposals. Nothing here changes a public page or price; the existing public prices (data/sponsorship_packages.json and the site payment settings) are untouched. Publishing a price is a separate owner decision.</div>'; if (!ad_ready($pdo)) return $o . '<div class="panel admErr">Needs the advertising migration.</div>'; $own = crm_can($user['role'] ?? null, 'approve');
  $o .= ad_table('Packages', ['Package', 'Price (proposed)', 'Billing / duration', 'Placement', 'Capacity', 'Available', ''], array_map(fn($p) => [ad_h($p['name']) . ($p['proposed'] ? ' <span class="small">(proposed)</span>' : ''), $p['price_minor'] === null ? 'On request' : ad_money((int)$p['price_minor'], (string)$p['currency']), ad_h((ad_billings()[$p['billing']] ?? $p['billing']) . ($p['duration_days'] ? ', ' . (int)$p['duration_days'] . ' days' : '')), ad_h($p['placement']), ad_h(($p['exclusive'] ? 'Exclusive' : (int)$p['slots'] . ' slot(s)') . ' per ' . ($p['scope'] === 'category' ? 'category' : ($p['scope'] === 'none' ? 'agreement' : 'site'))), $p['available'] ? 'Yes' : 'No', $own ? '<a class="admLink" href="' . ad_h(ad_url(['view' => 'packages', 'edit' => $p['id']])) . '">Edit</a>' : ''], ad_packages($pdo)));
  $inv = ad_inventory($pdo); $o .= '<h3>Inventory</h3>' . ad_table('Inventory', ['Package', 'Available', 'Capacity', 'Booked today', 'Booked in the next 90 days', 'Free today'], array_map(fn($i) => [ad_h($i['package']['name']), $i['available'] ? 'Yes' : 'No', ad_h((string)$i['capacity'] . ($i['scope'] === 'category' ? ' per category' : '')), (int)$i['booked_now'] . ($i['categories_booked'] ? ' (' . ad_h(implode(', ', $i['categories_booked'])) . ')' : ''), (int)$i['booked_90d'], !$i['available'] ? 'Not available' : ($i['free_now'] === null ? 'Per category' : (int)$i['free_now'])], $inv));
  $ex = ad_existing_listed_packages(); $o .= '<h3>Existing listed packages (read only)</h3><p class="small">Configured in data/sponsorship_packages.json and the site payment settings; managed with Tool management and the legacy payment flow. Shown for reference so nothing is duplicated.</p>' . ad_table('Existing packages', ['Package', 'Kind', 'Duration', 'Placement'], array_map(fn($k, $x) => [ad_h($x['label'] ?? $k), ad_h($x['kind'] ?? ''), ad_h($x['duration'] ?? ''), ad_h($x['placement'] ?? '')], array_keys($ex), array_values($ex)));
  if (!$own) return $o; $edit = (int)($_GET['edit'] ?? 0); $e = $edit ? ad_package_get($pdo, $edit) : null; $v = fn($k, $d = '') => (string)($e[$k] ?? $d);
  return $o . '<h3>' . ($e ? 'Edit package' : 'Add a package') . '</h3>' . ad_form('ad_package_save', $e ? ['id' => $e['id']] : [], admt_field('name', 'Name', $v('name'), []) . ad_select('kind', 'Kind', ad_kinds(), $v('kind', 'other')) . '<div class="row2">' . admt_field('price', 'Price (leave empty for on request)', $e && $e['price_minor'] !== null ? ad_minor((int)$e['price_minor']) : '', []) . ad_select('currency', 'Currency', array_combine(crm_currencies(), crm_currencies()), $v('currency', 'USD'), true) . '</div><div class="row2">' . ad_select('billing', 'Billing', ad_billings(), $v('billing', 'one_off')) . admt_field('duration_days', 'Duration (days, optional)', $v('duration_days'), []) . '</div>' . admt_field('placement', 'Placement', $v('placement'), []) . admt_area('description', 'Description', $v('description'), [])
    . '<div class="row2">' . admt_field('slots', 'Slots (capacity)', $v('slots', '1'), []) . ad_select('scope', 'Scope', ['global' => 'Whole site', 'category' => 'One per category', 'none' => 'Per agreement'], $v('scope', 'global')) . '</div>' . ad_select('public_slot', 'Public slot (uses the existing featured placement)', ['none' => 'None (booking, billing and reporting only)', 'level1' => 'Featured listing (level 1)', 'level2' => 'Homepage spotlight (level 2)'], $v('public_slot', 'none'))
    . '<label><input type="checkbox" name="exclusive" value="1"' . ($e && $e['exclusive'] ? ' checked' : '') . '> Exclusive (one booking at a time per scope)</label> <label><input type="checkbox" name="available" value="1"' . ($e && $e['available'] ? ' checked' : '') . '> Available for booking</label>', $e ? 'Save package' : 'Add package');
}
function ad_view_advertisers(PDO $pdo, array $user): string {
  $o = '<h2>Advertisers</h2><p class="small">An advertiser is an existing CRM company with at least one booking. Account manager, notes and the AI tools they own are kept here; contacts, enquiries and history stay in the CRM.</p>'; if (!ad_ready($pdo)) return $o . '<div class="panel admErr">Needs the advertising migration.</div>';
  $rows = $pdo->query("SELECT c.id, c.name, c.website, a.account_manager, u.display_name mgr, a.notes, (SELECT COUNT(*) FROM ad_booking b WHERE b.company_id = c.id) n, (SELECT COUNT(*) FROM ad_booking b WHERE b.company_id = c.id AND b.status IN ('active','paused')) act FROM crm_companies c JOIN ad_advertiser a ON a.company_id = c.id LEFT JOIN crm_users u ON u.id = a.account_manager ORDER BY c.name")->fetchAll(PDO::FETCH_ASSOC); $w = crm_can($user['role'] ?? null, 'write'); $users = ad_user_options($pdo); $cat = ad_catalogue();
  foreach ($rows as $r) { $tools = ad_advertiser_tools($pdo, (int)$r['id']); $o .= '<div class="panel"><h3 style="margin-top:0">' . crm_link('company', (int)$r['id'], (string)$r['name']) . '</h3><p class="small">' . ad_h($r['website'] ?: '—') . ' · bookings ' . (int)$r['n'] . ' (' . (int)$r['act'] . ' active) · manager ' . ad_h($r['mgr'] ?: '—') . ' · tools: ' . ad_h(implode(', ', array_map(fn($t) => $cat[$t]['name'] ?? $t, $tools)) ?: '—') . '</p>'
    . ($w ? ad_form('ad_advertiser_update', ['company_id' => $r['id']], ad_select('account_manager', 'Account manager', $users, (string)$r['account_manager'], true) . admt_area('notes', 'Internal notes', (string)$r['notes'], []), 'Save', 'tInline') . ad_form('ad_advertiser_tool', ['company_id' => $r['id']], ad_select('tool_slug', 'Associate an AI tool', ad_tool_options(), ''), 'Add tool', 'tInline') : '') . '</div>'; }
  return $o . (!$rows ? '<p class="small">No advertisers yet: create a booking for a CRM company.</p>' : '');
}
function ad_view_opportunities(PDO $pdo, array $user): string {
  $r = ad_opportunities($pdo); $o = '<h2>Advertising sales opportunities</h2><p class="small">Built from measured clicks (last 90 days), recorded enquiries and your own research. No audience, traffic or conversion figure is invented, and nothing is sent: outreach drafts are text for a person to review.</p>'; if (!$r['ready']) return $o . '<div class="panel admErr">Needs the advertising migration.</div>';
  if ($r['analytics'] === false) $o .= '<div class="panel admErr" role="status">Click analytics storage is not installed, so click-based rankings are unavailable (not zero).</div>';
  $o .= '<h3>Most-clicked AI tools (outbound clicks, 90 days)</h3>' . ad_table('Most clicked tools', ['Tool', 'Category', 'Outbound clicks', 'Sponsorship'], array_map(fn($t) => [ad_h($t['name']), ad_h($t['category']), (int)$t['outbound'], $t['booked'] ? 'Booked' : 'Open'], $r['tools']), $r['analytics'] === false ? 'Unavailable without click analytics.' : 'No outbound clicks recorded in the period.');
  $o .= '<h3>High-traffic categories</h3>' . ad_table('High traffic categories', ['Category', 'Outbound clicks', 'Tools with clicks', 'Category sponsor'], array_map(fn($c) => [ad_h($c['category']), (int)$c['outbound'], (int)$c['tools'], $c['sponsored'] ? 'Booked' : 'Open'], $r['categories']), 'None recorded.');
  $o .= '<h3>Available sponsorship inventory</h3>' . ad_table('Inventory', ['Package', 'Available', 'Free today'], array_map(fn($i) => [ad_h($i['package']['name']), $i['available'] ? 'Yes' : 'No', !$i['available'] ? 'Not available' : ($i['free_now'] === null ? 'Per category' : (int)$i['free_now'])], $r['inventory']));
  $o .= '<h3>Advertisers eligible for renewal</h3><p class="small">Campaign ended in the last 60 days or ends within 30 days, and no later booking exists.</p>' . ad_table('Renewals', ['Advertiser', 'Last campaign ends', 'Bookings'], array_map(fn($x) => [crm_link('company', (int)$x['company_id'], (string)$x['company']), ad_h($x['last_end']), (int)$x['n']], $r['renewals']), 'No advertiser is currently due for a renewal conversation.');
  $o .= '<h3>Companies with recorded advertising enquiries</h3>' . ad_table('Enquiries', ['Company', 'Received', 'Lead status', 'Bookings'], array_map(fn($x) => [crm_link('company', (int)$x['company_id'], (string)$x['company']), ad_h(substr($x['created_at'], 0, 10)), ad_h($x['status']), (int)$x['bookings']], $r['enquiries']), 'No open advertising enquiries recorded.');
  $o .= '<h3>Potential advertising partners (your own research)</h3><p class="small">Prospects you recorded as advertising prospects (not marked not-a-fit, not already advertisers). Drafts are refused for prospects marked not a fit or archived, or whose company has an unsubscribed contact. This page never sends anything.</p>';
  $o .= ad_table('Potential partners', ['Company', 'Website', 'Fit', 'Draft'], array_map(fn($x) => [ad_h($x['company_name']), ad_h($x['website'] ?: '—'), ad_h(crm_prospect_fit_statuses()[$x['fit_status']] ?? ''), crm_can($user['role'] ?? null, 'outreach') ? ad_form('ad_outreach_draft', ['prospect_id' => $x['id']], '', 'Create editable draft', 'tInline') : ''], $r['partners']), 'No advertising prospects recorded yet (add them in the CRM, Prospects).'); return $o . '<p class="small">Drafts open in the CRM <a href="/crm.php?v=outreach">Outreach drafts</a> page, where they can be edited and reviewed.</p>';
}
function ad_nav(string $role, string $view): string { $o = '<nav aria-label="Advertising sections" class="crmNav">'; foreach (admv_views() as $k => [$l, $perm]) if (!in_array($k, ['booking', 'report'], true) && adm_can($role, $perm)) $o .= '<a class="btn sm' . ($k === $view ? '' : ' secondary') . '" href="' . ad_h(ad_url(['view' => $k])) . '"' . ($k === $view ? ' aria-current="page"' : '') . '>' . ad_h($l) . '</a> '; return $o . '</nav>'; }
function ad_body(PDO $pdo, array $user, array $get): string {
  $view = admv_view($get, (string)$user['role']); $msg = isset($get['msg']) && is_string($get['msg']) ? '<div class="panel" role="status">' . ad_h(ad_msg($get['msg'])) . '</div>' : '';
  $b = match ($view) { 'revenue' => ad_view_revenue($pdo), 'bookings' => ad_view_bookings($pdo, $get, $user), 'booking' => ad_view_booking($pdo, (int)($get['id'] ?? 0), $user), 'packages' => ad_view_packages($pdo, $user), 'advertisers' => ad_view_advertisers($pdo, $user), 'opportunities' => ad_view_opportunities($pdo, $user), default => '' };
  return ad_wrap('<div class="admCrm admAdv"><h1>Advertising</h1>' . ad_nav((string)$user['role'], $view === 'booking' ? 'bookings' : $view) . $msg . $b . '</div>');
}
function ad_handle_post(PDO $pdo, array $user, array $p): array {
  $a = (string)($p['act'] ?? ''); $s = fn($k) => (string)($p[$k] ?? ''); $id = (int)($p['id'] ?? 0); $go = ['view' => 'bookings']; $r = [false, 'unknown_action']; $bf = fn() => ['package_id' => $s('package_id'), 'tool_slug' => $s('tool_slug'), 'category' => $s('category'), 'agreed_price' => $s('agreed_price'), 'currency' => $s('currency'), 'billing' => $s('billing'), 'start_date' => $s('start_date'), 'end_date' => $s('end_date'), 'renewal_date' => $s('renewal_date'), 'payment_link' => $s('payment_link'), 'account_manager' => $s('account_manager'), 'requirements' => $s('requirements'), 'notes' => $s('notes')];
  switch ($a) {
    case 'ad_booking_create': $r = ad_booking_create($pdo, $user, (int)$s('company_id'), $bf()); if ($r[0]) $go = ['view' => 'booking', 'id' => (int)$r[1]]; break;
    case 'ad_booking_adopt': $r = ad_booking_create($pdo, $user, (int)$s('company_id'), [], (int)$s('campaign_id')); if ($r[0]) $go = ['view' => 'booking', 'id' => (int)$r[1]]; break;
    case 'ad_booking_update': $r = ad_booking_update($pdo, $user, $id, $bf()); $go = ['view' => 'booking', 'id' => $id]; break;
    case 'ad_booking_move': $r = ad_booking_move($pdo, $user, $id, $s('to'), $s('note')); $go = ['view' => 'booking', 'id' => $id]; break;
    case 'ad_booking_activate': $r = ad_booking_activate($pdo, $user, $id, $s('confirm') === '1'); $go = ['view' => 'booking', 'id' => $id]; if ($r[0] && $r[1] !== 'ok') $r = [false, $r[1]]; break;
    case 'ad_agreement': $r = ad_booking_create_agreement($pdo, $user, $id, $s('confirm') === '1'); $go = ['view' => 'booking', 'id' => $id]; break;
    case 'ad_agreement_confirm': $r = ad_booking_confirm_agreement($pdo, $user, $id); $go = ['view' => 'booking', 'id' => $id]; break;
    case 'ad_payment': $r = ad_record_payment($pdo, $user, $id, $s('kind'), $s('amount'), $s('date'), $s('reference')); $go = ['view' => 'booking', 'id' => $id]; break;
    case 'ad_package_save': $r = ad_package_save($pdo, $user, $id ?: null, ['name' => $s('name'), 'kind' => $s('kind'), 'price' => $s('price'), 'currency' => $s('currency'), 'duration_days' => $s('duration_days'), 'billing' => $s('billing'), 'placement' => $s('placement'), 'description' => $s('description'), 'slots' => $s('slots') ?: '1', 'scope' => $s('scope'), 'public_slot' => $s('public_slot'), 'exclusive' => $s('exclusive'), 'available' => $s('available')]); $go = ['view' => 'packages']; break;
    case 'ad_advertiser_update': $r = ad_advertiser_update($pdo, $user, (int)$s('company_id'), $s('account_manager') === '' ? null : (int)$s('account_manager'), $s('notes')); $go = ['view' => 'advertisers']; break;
    case 'ad_advertiser_tool': $r = ad_advertiser_tool_add($pdo, $user, (int)$s('company_id'), $s('tool_slug')); $go = ['view' => 'advertisers']; break;
    case 'ad_outreach_draft': $tp = crm_outreach_templates()['advertiser_intro']; $r = ad_outreach_draft($pdo, $user, (int)$s('prospect_id'), $tp['subject'], $tp['body']); $go = ['view' => 'opportunities']; break;
    case 'ad_sweep': if (ad_deny($user, 'approve')) { $r = [false, 'forbidden']; } else { ad_sweep($pdo, $user); $r = [true, 'ok']; } $go = ['view' => 'bookings']; break;
  }
  return ['redirect' => ad_url($go + ['msg' => $r[0] ? ($r[1] === 'approved_for_start_date' ? 'approved_for_start_date' : 'ok') : (string)$r[1]])];
}
